export function isClientMonitorIssue(e){switch(e.type){case"cpulimitation":case"congestion":case"audio-desync":case"dry-inbound-track":case"dry-outbound-track":case"freezed-video-track":case"inbound-video-playout-discrepancy":case"unstable-ice-path":case"ice-disconnected":case"ice-connection-failed":case"ice-transport-stalled":case"audio-concealment":case"audio-jitter-buffer-stress":case"video-decoder-overloaded":case"keyframe-storm":case"video-recovery-failed":case"capture-bottleneck":case"encoder-bottleneck":case"capture-track-ended":case"silent-audio-source":case"stuck-decoder":return!0;default:return!1}}export function isClientMonitorResolvedIssue(e){return isClientMonitorIssue(e)}